x 0}.green-line:before{background:var(--green)}.yellow-line:before{background:var(--yellow)}.purple-line:before{background:var(--purple)}canvas{width:100%;height:330px;display:block}.settings-card h2{font-size:20px;margin:0 0 7px}.settings-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:17px}.field{display:flex;flex-direction:column;gap:7px}.field input,.field select{padding:12px;border:1px solid #dfe4ed;border-radius:10px;width:100%;min-width:0}.small-note{font-size:12px;color:var(--muted);line-height:1.5}.table-card{padding:0;overflow:hidden}.table-top{padding:20px 22px}.table-top h2{margin:0 0 7px;font-size:20px}.table-top p{margin:0;color:var(--muted);font-size:13px}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:580px}th,td{text-align:left;padding:13px 20px;border-top:1px solid var(--line);font-size:14px}th{background:#fafbfe;color:var(--muted);font-size:12px}.empty{padding:25px;color:var(--muted);text-align:center}.bottom-nav{position:fixed;bottom:0;left:0;width:100%;background:white;display:flex;justify-content:space-around;border-top:1px solid #ddd;padding:10px 0;z-index:10}.bottom-nav a{text-decoration:none;color:#777;font-size:12px;align-items:center;flex-direction:column;display:flex;gap:4px;text-align:center}.bottom-nav .active{color:var(--blue);font-weight:700}.btn{border:0;background:var(--blue);color:white;font-weight:700;padding:12px 16px;border-radius:11px}.modal-backdrop{display:none;position:fixed;inset:0;background:#10182888;z-index:30;align-items:center;justify-content:center;padding:15px}.modal-backdrop.show{display:flex}.modal{background:white;border-radius:18px;width:min(540px,100%);padding:22px}.modal-head{display:flex;justify-content:space-between;align-items:center}.modal-head h2{font-size:20px;margin:0}.modal-fields{display:grid;gap:15px;margin:20px 0}.modal-actions{display:flex;justify-content:flex-end;gap:10px}.btn-light{border:0;background:var(--pale);color:var(--blue);font-weight:700;padding:12px 16px;border-radius:11px}.toast{display:none;position:fixed;bottom:80px;left:50%;transform:translateX(-50%);background:#172033;color:white;padding:12px 16px;border-radius:10px;z-index:50;max-width:90%}.toast.show{display:block}
