<div class="modal-backdrop" id="filterModal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal"><div class="modal-head"><h2 id="modalTitle">Pengaturan Analisis</h2><button class="btn-light" id="closeModal">Tutup</button></div><p class="small-note">Atur parameter analisis di sini. Perubahan akan langsung memperbarui angka dan grafik.</p><div class="modal-fields"><div class="field"><label for="modalFixed">Biaya tetap per bulan (Rp)</label><input id="modalFixed" type="number" min="0" step="1000"></div><div class="field"><label for="modalTarget">Target laba per bulan (Rp)</label><input id="modalTarget" type="number" min="0" step="100000"></div><div class="field"><label for="modalRange">Rentang grafik (porsi)</label><input id="modalRange" type="number" min="10" step="10"></div></div><div class="modal-actions"><button class="btn-light" id="cancelModal">Batal</button><button class="btn" id="applyModal">Terapkan</button></div></div></div><div class="toast" id="toast" role="status"></div>
<script>
(function(){
'use strict';
const $=id=>document.getElementById(id),fmt=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(n)||0),num=n=>Number(n)||0;
const PRODUCT_KEY='kuliko_produk_resep_v1',HPP_KEY='kuliko_hpp_data_v1';
let products=[],hppData={},activeId='',toastTimer;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch(e){return fallback}}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600)}
function materialCost(p){return(Array.isArray(p.ingredients)?p.ingredients:[]).reduce((s,i)=>s+num(i.qty)*num(i.price),0)}
function hppForProduct(p){const h=hppData[p.id];if(h){const materials=(h.materials||[]).reduce((s,i)=>s+num(i.qty)*num(i.price),0),labor=(h.labor||[]).reduce((s,i)=>s+num(i.cost),0),overhead=(h.overhead||[]).reduce((s,i)=>s+num(i.cost),0);return materials+labor+overhead}return materialCost(p)}
function entries(){const result=[];products.forEach(p=>result.push({id:p.id,name:p.name||'Produk tanpa nama',price:num(p.sellingPrice),hpp:hppForProduct(p),source:'product'}));Object.values(hppData).forEach(h=>{if(h&&h.source==='simulation'&&!products.some(p=>p.id===h.id))result.push({id:h.id,name:h.name||'Simulasi HPP',price:num(h.sellingPrice),hpp:(h.materials||[]).reduce((s,i)=>s+num(i.qty)*num(i.price),0)+(h.labor||[]).reduce((s,i)=>s+num(i.cost),0)+(h.overhead||[]).reduce((s,i)=>s+num(i.cost),0),source:'simulation'})});return result}
function current(){return entries().find(p=>p.id===activeId)||null}
function load(){products=read(PRODUCT_KEY,[]);if(!Array.isArray(products))products=[];hppData=read(HPP_KEY,{});if(!hppData||typeof hppData!=='object'||Array.isArray(hppData))hppData={};const all=entries();if(!all.some(p=>p.id===activeId))activeId=all[0]?.id||'';render()}
function updateOptions(){const sel=$('productSelect'),all=entries();sel.innerHTML='';if(!all.length){sel.innerHTML='<option value="">Belum ada produk</option>';activeId='';return}all.forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name+(p.source==='simulation'?' · Simulasi':'');sel.appendChild(o)});if(!all.some(p=>p.id===activeId))activeId=all[0].id;sel.value=activeId}
function params(){return{fixed:Math.max(0,num($('fixedCost').value)),target:Math.max(0,num($('targetProfit').value)),range:Math.max(10,Math.floor(num($('chartMax').value)||1000))}}
function render(){updateOptions();const p=current(),a=params();if(!p){$('productHint').textContent='Belum ada produk. Tambahkan produk di halaman Produk & Resep atau buat simulasi di halaman Hitung HPP.';$('profitValue').textContent=fmt(0);$('marginValue').textContent='Margin —';$('sellValue').textContent=fmt(0);$('hppValue').textContent='HPP '+fmt(0);$('bepUnits').textContent='—';$('bepRevenue').textContent='Pendapatan BEP —';$('targetValue').textContent=fmt(a.target);$('targetUnits').textContent='Belum dapat dihitung';$('chartNote').textContent='Grafik akan tersedia setelah ada produk dengan harga jual dan HPP.';$('decisionRows').innerHTML='<tr><td colspan="3" class="empty">Belum ada data produk untuk dianalisis.</td></tr>';drawChart(null,a);return}
const profit=p.price-p.hpp,margin=p.price>0?profit/p.price*100:null,contribution=profit,bep=contribution>0?Math.ceil(a.fixed/contribution):null,targetUnits=contribution>0?Math.ceil((a.fixed+a.target)/contribution):null;
$('productHint').textContent=(p.source==='simulation'?'Produk simulasi dari halaman Hitung HPP.':'Data produk dari halaman Produk & Resep.')+' Periksa harga jual dan biaya jika hasil belum sesuai.';
$('profitValue').textContent=fmt(profit);$('profitValue').style.color=profit<0?'#d9534f':'var(--blue)';$('marginValue').textContent='Margin '+(margin===null?'—':margin.toLocaleString('id-ID',{maximumFractionDigits:1})+'%');$('sellValue').textContent=fmt(p.price);$('hppValue').textContent='HPP '+fmt(p.hpp);$('bepUnits').textContent=bep===null?'Tidak tercapai':bep.toLocaleString('id-ID')+' porsi';$('bepRevenue').textContent=bep===null?'Harga jual harus melebihi HPP':fmt(bep*p.price);$('targetValue').textContent=fmt(a.target);$('targetUnits').textContent=targetUnits===null?'Target tidak tercapai':targetUnits.toLocaleString('id-ID')+' porsi per bulan';
$('chartNote').textContent=bep===null?'BEP tidak dapat dihitung karena kontribusi per porsi nol atau negatif.':`Titik BEP diperkirakan pada ${bep.toLocaleString('id-ID')} porsi, dengan pendapatan ${fmt(bep*p.price)}. Perhitungan menganggap harga dan biaya per porsi tetap.`;
const rows=[['Harga jual per porsi',fmt(p.price),p.price>0?'Harga jual tersedia':'Isi harga jual di halaman Produk atau HPP'],['HPP per porsi',fmt(p.hpp),p.hpp>0?'Biaya produksi tercatat':'Tambahkan bahan dan biaya pada halaman HPP'],['Profit per porsi',fmt(profit),profit>0?'Setiap porsi memberi kontribusi untuk menutup biaya tetap':profit===0?'Harga jual sama dengan HPP':'HPP melebihi harga jual; evaluasi biaya atau harga'],['BEP unit',bep===null?'Tidak tercapai':bep.toLocaleString('id-ID')+' porsi',bep===null?'Perlu profit per porsi positif':'Target minimal penjualan untuk menutup biaya tetap'],['Target laba',targetUnits===null?'Tidak tercapai':targetUnits.toLocaleString('id-ID')+' porsi',targetUnits===null?'Perlu profit per porsi positif':'Estimasi penjualan bulanan untuk mencapai target']];$('decisionRows').innerHTML=rows.map(r=>`<tr><td>${r[0]}</td><td><strong>${r[1]}</strong></td><td>${r[2]}</td></tr>`).join('');drawChart(p,a)}
function drawChart(p,a){const canvas=$('bepChart'),ctx=canvas.getContext('2d'),rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(300,rect.width),h=Math.max(220,rect.height);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const left=68,right=18,top=20,bottom=42,pw=w-left-right,ph=h-top-bottom;if(!p){ctx.fillStyle='#6b7280';ctx.font='14px Arial';ctx.textAlign='center';ctx.fillText('Belum ada data produk',w/2,h/2);return}
const maxX=a.range,fixed=a.fixed,price=p.price,hpp=p.hpp,variable=hpp;const maxY=Math.max(price*maxX,fixed+variable*maxX,1)*1.08;
const x=n=>left+(n/maxX)*pw,y=n=>top+ph-(n/maxY)*ph;
ctx.font='11px Arial';ctx.textAlign='right';ctx.textBaseline='middle';ctx.strokeStyle='#e7ebf2';ctx.fillStyle='#6b7280';
for(let i=0;i<=4;i++){const val=maxY*i/4,yy=y(val);ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.fillText(shortMoney(val),left-8,yy)}
ctx.textAlign='center';ctx.textBaseline='top';for(let i=0;i<=4;i++){const val=maxX*i/4,xx=x(val);ctx.fillText(Math.round(val).toLocaleString('id-ID'),xx,h-bottom+10)}
ctx.fillStyle='#6b7280';ctx.fillText('Jumlah porsi',left+pw/2,h-17);
function line(color,fn){ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.beginPath();for(let i=0;i<=100;i++){const units=maxX*i/100,xx=x(units),yy=y(fn(units));if(i===0)ctx.moveTo(xx,yy);else ctx.lineTo(xx,yy)}ctx.stroke()}
line('#1bb76e',n=>price*n);line('#e6ad28',n=>fixed+variable*n);line('#7b61ff',()=>fixed);
const contribution=price-hpp;if(contribution>0){const be=a.fixed/contribution;if(be<=maxX){ctx.fillStyle='#172033';ctx.beginPath();ctx.arc(x(be),y(price*be),4,0,Math.PI*2);ctx.fill();ctx.font='11px Arial';ctx.textAlign='left';ctx.fillText('BEP '+Math.ceil(be),Math.min(x(be)+7,w-80),Math.max(top+3,y(price*be)-17))}}
function shortMoney(n){if(n>=1e6)return 'Rp '+(n/1e6).toLocaleString('id-ID',{maximumFractionDigits:1})+' jt';if(n>=1000)return 'Rp '+(n/1000).toLocaleString('id-ID',{maximumFractionDigits:0})+' rb';return 'Rp '+Math.round(n)}
}
$('productSelect').addEventListener('change',e=>{activeId=e.target.value;render()});
['fixedCost','targetProfit','chartMax'].forEach(id=>$(id).addEventListener('input',render));
$('filterBtn').addEventListener('click',()=>{const a=params();$('modalFixed').value=a.fixed;$('modalTarget').value=a.target;$('modalRange').value=a.range;$('filterModal').classList.add('show')});
function closeModal(){$('filterModal').classList.remove('show')}
$('closeModal').addEventListener('click',closeModal);$('cancelModal').addEventListener('click',closeModal);$('filterModal').addEventListener('click',e=>{if(e.target===$('filterModal'))closeModal()});
$('applyModal').addEventListener('click',()=>{[['modalFixed','fixedCost'],['modalTarget','targetProfit'],['modalRange','chartMax']].forEach(([from,to])=>$(to).value=$(from).value);closeModal();render();toast('Pengaturan analisis diperbarui.')});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});window.addEventListener('resize',()=>drawChart(current(),params()));window.addEventListener('storage',e=>{if([PRODUCT_KEY,HPP_KEY].includes(e.key))load()});load();
})();
</script></body></html>